import json
d=json.load(open('apple.json'))
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text': out.append(o.get('text',''))
        elif o.get('type')=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        elif o.get('type')=='reference': out.append('['+str(o.get('identifier','')).split('/')[-1]+']')
        elif o.get('type')=='paragraph' or o.get('type')=='heading':
            for v in o.values(): walk(v,out)
            out.append('\n\n')
            return
        for v in o.values(): walk(v,out)
    elif isinstance(o,list):
        for v in o: walk(v,out)
out=[]
walk(d.get('abstract'),out); out.append('\n\n')
walk(d.get('primaryContentSections'),out)
print(''.join(out))
print('=== METADATA ===')
print(json.dumps(d.get('metadata'),indent=1))
